import swaggerJSDoc from "swagger-jsdoc";
import swaggerUi from "swagger-ui-express";
import { PORT } from "./env.js";

const port = PORT || 3000;

const options = {
  definition: {
    openapi: "3.0.0",
    info: {
      title: "Ledger API",
      version: "1.0.0",
      description:
        "API documentation for the Ledger application. Transaction records are immutable, and all identifiers and timestamps are generated by the server. Money values use major currency units with at most two decimal places in requests and responses.",
    },
    servers: [
      {
        url: `http://localhost:${port}`,
        description: "Development Server",
      },
    ],
    components: {
      securitySchemes: {
        bearerAuth: {
          type: "http",
          scheme: "bearer",
          bearerFormat: "JWT",
        },
      },
      schemas: {
        ErrorResponse: {
          type: "object",
          required: ["success", "error"],
          properties: {
            success: {
              type: "boolean",
              example: false,
            },
            error: {
              type: "string",
              description: "Human-readable error message.",
              example: "Invalid request",
            },
          },
        },
        Account: {
          type: "object",
          required: ["id", "name", "balance", "created_at"],
          properties: {
            id: {
              type: "string",
              description: "Public account identifier.",
              example: "665f1c2a9b1e8a0012a4d3f1",
            },
            name: {
              type: "string",
              description: "Account holder name.",
              example: "Ada Lovelace",
            },
            balance: {
              type: "number",
              description:
                "Current balance in major currency units with two decimal places. New accounts always start at 0.",
              example: 0,
            },
            created_at: {
              type: "string",
              format: "date-time",
              description: "Server-generated account creation timestamp (UTC).",
              example: "2026-10-27T10:00:00.000Z",
            },
          },
        },
        Transaction: {
          type: "object",
          description:
            "An immutable ledger entry. Its identifier and created_at timestamp are server-generated; no update or delete operation exists.",
          required: [
            "id",
            "account_id",
            "type",
            "amount",
            "description",
            "reference_id",
            "created_at",
          ],
          properties: {
            id: {
              type: "string",
              description: "Public transaction identifier.",
              example: "666f1c2a9b1e8a0012a4d3f2",
            },
            account_id: {
              type: "string",
              description: "Account that owns this ledger entry.",
              example: "665f1c2a9b1e8a0012a4d3f1",
            },
            type: {
              type: "string",
              enum: ["credit", "debit"],
              description: "Whether the entry increases or decreases the balance.",
              example: "credit",
            },
            amount: {
              type: "number",
              description:
                "Transaction amount in major currency units with at most two decimal places.",
              example: 125.5,
            },
            description: {
              type: "string",
              description: "Human-readable transaction description.",
              example: "Invoice payment",
            },
            reference_id: {
              type: "string",
              description:
                "Caller-supplied reference ID. It is unique within one account and may be reused by another account.",
              example: "INV-2026-001",
            },
            created_at: {
              type: "string",
              format: "date-time",
              description: "Server-generated transaction timestamp (UTC).",
              example: "2026-10-27T10:05:00.000Z",
            },
          },
        },
        Transfer: {
          type: "object",
          required: [
            "reference_id",
            "amount",
            "description",
            "source_account_id",
            "destination_account_id",
            "created_at",
          ],
          properties: {
            reference_id: {
              type: "string",
              description:
                "Transfer reference recorded on both ledger entries. It must be unused by both accounts.",
              example: "TRF-2026-001",
            },
            amount: {
              type: "number",
              description:
                "Transferred amount in major currency units with at most two decimal places.",
              example: 25,
            },
            description: {
              type: "string",
              description: "Human-readable transfer description.",
              example: "Rent share",
            },
            source_account_id: {
              type: "string",
              description: "Account debited by the transfer.",
              example: "665f1c2a9b1e8a0012a4d3f1",
            },
            destination_account_id: {
              type: "string",
              description: "Account credited by the transfer.",
              example: "666f1c2a9b1e8a0012a4d3f2",
            },
            created_at: {
              type: "string",
              format: "date-time",
              description: "Server-generated transfer timestamp (UTC).",
              example: "2026-10-27T10:10:00.000Z",
            },
          },
        },
      },
    },
  },
  apis: ["./routes/*.js", "./routes/**/*.js", "./app.js"],
};

const swaggerSpec = swaggerJSDoc(options);

const setupSwagger = (app) => {
  // Swagger UI page
  app.use("/api-docs", swaggerUi.serve, swaggerUi.setup(swaggerSpec));

  // Swagger specification JSON
  app.get("/api-docs.json", (req, res) => {
    res.setHeader("Content-Type", "application/json");
    res.send(swaggerSpec);
  });
};

export { swaggerSpec, setupSwagger };
export default setupSwagger;
